const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the local community theatre group information desk.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.106916666666667},{"speaker":"B","text":"Good morning because I want to join the evening drama classes for beginners.","position":2,"audioStartSeconds":5.306916666666667,"audioEndSeconds":9.885125},{"speaker":"A","text":"We rehearse every Tuesday evening in the main hall from seven until nine.","position":3,"audioStartSeconds":10.085125,"audioEndSeconds":14.893791666666667},{"speaker":"B","text":"That time works well for me although the fee is my main concern.","position":4,"audioStartSeconds":15.093791666666666,"audioEndSeconds":19.33425},{"speaker":"A","text":"The annual membership fee is forty pounds which includes all rehearsal materials.","position":5,"audioStartSeconds":19.53425,"audioEndSeconds":24.895041666666668},{"speaker":"B","text":"Actually I thought it might be fifty pounds so that is very reasonable.","position":6,"audioStartSeconds":25.095041666666667,"audioEndSeconds":29.669791666666665},{"speaker":"A","text":"You must complete a simple registration form before your first session.","position":7,"audioStartSeconds":29.869791666666668,"audioEndSeconds":34.418791666666664},{"speaker":"B","text":"Should I bring any special clothing for the movement exercises?","position":8,"audioStartSeconds":34.61879166666667,"audioEndSeconds":38.60075},{"speaker":"A","text":"Please wear comfortable clothing since we do active warm up games.","position":9,"audioStartSeconds":38.80075,"audioEndSeconds":43.05254166666667},{"speaker":"B","text":"Can I bring my running shoes for the indoor stage floor?","position":10,"audioStartSeconds":43.252541666666666,"audioEndSeconds":46.860791666666664},{"speaker":"A","text":"Soft shoes are required because heavy trainers might damage the wooden floor.","position":11,"audioStartSeconds":47.06079166666667,"audioEndSeconds":51.81670833333333},{"speaker":"B","text":"I will buy some black pumps before Tuesday if possible.","position":12,"audioStartSeconds":52.016708333333334,"audioEndSeconds":55.94708333333333},{"speaker":"A","text":"That sounds perfect and please bring a notebook for your script notes.","position":13,"audioStartSeconds":56.147083333333335,"audioEndSeconds":60.424375},{"speaker":"B","text":"Thank you for your helpful guidance today.","position":14,"audioStartSeconds":60.624375,"audioEndSeconds":63.66354166666667}],"questions":[{"prompt":"Rehearsal day: ______","answer":"Tuesday","evidenceSentence":3,"evidence":"We rehearse every Tuesday evening in the main hall from seven until nine.","explanation":"Người nói A cho biết buổi tập diễn ra vào mỗi tối thứ Ba (Tuesday)."},{"prompt":"Annual membership fee: ______ pounds","answer":"forty","evidenceSentence":5,"evidence":"The annual membership fee is forty pounds which includes all rehearsal materials.","explanation":"Lệ phí thường niên được nêu rõ là forty (bốn mươi) bảng, sửa lại ý kiến ban đầu là fifty."},{"prompt":"Required document: ______ form","answer":"registration","evidenceSentence":7,"evidence":"You must complete a simple registration form before your first session.","explanation":"Học viên phải hoàn thành một mẫu đăng ký (registration form) đơn giản trước buổi học đầu tiên."},{"prompt":"Clothing requirement: ______ clothing","answer":"comfortable","evidenceSentence":9,"evidence":"Please wear comfortable clothing since we do active warm up games.","explanation":"Yêu cầu về trang phục là mặc đồ thoải mái (comfortable clothing) vì có các trò chơi khởi động."},{"prompt":"Footwear requirement: ______ shoes","answer":"Soft","evidenceSentence":11,"evidence":"Soft shoes are required because heavy trainers might damage the wooden floor.","explanation":"Yêu cầu mang giày mềm (Soft shoes) thay vì giày thể thao nặng để tránh hỏng sàn gỗ."},{"prompt":"Item to bring for script notes: ______","answer":"notebook","evidenceSentence":13,"evidence":"That sounds perfect and please bring a notebook for your script notes.","explanation":"Người tham gia được yêu cầu mang theo một cuốn sổ (notebook) để ghi chú kịch bản."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
